import { Capacitor } from '@capacitor/core'
import { PushNotifications } from '@capacitor/push-notifications'
import { supabase } from './supabase'

// Push only exists inside the Android app. On the web these functions do nothing.
// The notification text is generated by the server and never contains message content.

const TOKEN_KEY = 'dt:pushtoken'
let listening = false
let pendingChat: string | null = null
let opener: ((chatId: string) => void) | null = null

/** What this device knows about its own push setup, shown in Settings so problems are visible without a debugger. */
export interface PushStatus {
  supported: boolean
  permission: 'unknown' | 'granted' | 'denied' | 'prompt'
  registered: boolean // this device's token was saved on the server
  error: string
}

const status: PushStatus = { supported: Capacitor.isNativePlatform(), permission: 'unknown', registered: false, error: '' }
const subscribers = new Set<() => void>()
const update = (patch: Partial<PushStatus>) => {
  Object.assign(status, patch)
  subscribers.forEach((f) => f())
}

export const getPushStatus = (): PushStatus => ({ ...status })
export function onPushStatus(cb: () => void): () => void {
  subscribers.add(cb)
  return () => void subscribers.delete(cb)
}

const store = {
  get: () => {
    try {
      return localStorage.getItem(TOKEN_KEY)
    } catch {
      return null
    }
  },
  set: (t: string | null) => {
    try {
      if (t) localStorage.setItem(TOKEN_KEY, t)
      else localStorage.removeItem(TOKEN_KEY)
    } catch {
      /* storage unavailable: token is simply re-registered next launch */
    }
  },
}

/** The UI registers here to be told when a notification was tapped. A tap that happened earlier is delivered immediately. */
export function onOpenChat(cb: (chatId: string) => void): () => void {
  opener = cb
  if (pendingChat) {
    cb(pendingChat)
    pendingChat = null
  }
  return () => {
    if (opener === cb) opener = null
  }
}

async function listen() {
  if (listening) return
  listening = true
  await PushNotifications.addListener('registration', async ({ value }) => {
    store.set(value)
    const { error } = await supabase.rpc('register_push_token', { p_token: value, p_platform: 'android' })
    update({ registered: !error, error: error ? `Could not save the device on the server: ${error.message}` : '' })
  })
  // Typically "Default FirebaseApp is not initialized": this APK was built without a valid google-services.json
  await PushNotifications.addListener('registrationError', ({ error }) => update({ registered: false, error: `Firebase registration failed: ${error}` }))
  await PushNotifications.addListener('pushNotificationActionPerformed', ({ notification }) => {
    const chatId = (notification.data as { chatId?: string } | undefined)?.chatId
    if (!chatId) return
    if (opener) opener(chatId)
    else pendingChat = chatId
  })
  await PushNotifications.createChannel({ id: 'messages', name: 'Messages', description: 'New chat messages and secrets', importance: 4 })
}

/** Safe to call again: asks for permission if needed and (re)registers this device. */
export async function startPush(): Promise<void> {
  if (!Capacitor.isNativePlatform()) return
  try {
    await listen()
    let perm = await PushNotifications.checkPermissions()
    if (perm.receive.startsWith('prompt')) perm = await PushNotifications.requestPermissions()
    const p = perm.receive.startsWith('prompt') ? 'prompt' : (perm.receive as PushStatus['permission'])
    update({ permission: p, error: p === 'denied' ? 'Notifications are blocked for this app. Turn them on in Android Settings > Apps > DataTransfer > Notifications.' : '' })
    if (perm.receive === 'granted') await PushNotifications.register()
  } catch (e) {
    update({ registered: false, error: `Push setup failed: ${(e as Error).message}` })
  }
}

/** Call before signing out, while the session is still valid, so this device stops getting the account's pushes. */
export async function stopPush(): Promise<void> {
  const token = store.get()
  if (!token) return
  try {
    await supabase.rpc('unregister_push_token', { p_token: token })
  } catch {
    /* offline: the server drops the token the next time FCM reports it dead */
  }
  store.set(null)
  update({ registered: false })
}
